import React, { useState, useEffect } from 'react';
import axios from 'axios'; // Đảm bảo bạn đã cài axios: npm install axios
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const DangKyBaiDoXe = () => {
    const [selectedSlot, setSelectedSlot] = useState(null);
    const [loading, setLoading] = useState(false);
    const [allSlotsData, setAllSlotsData] = useState([]); // Lưu trạng thái từ MySQL
    const [userInfo, setUserInfo] = useState({ id: '', name: '', room: '' });

    // Tạo danh sách 40 vị trí đỗ
    const zones = ['A', 'B', 'C', 'D'];
    const allSlots = [];
    zones.forEach(zone => {
        for (let i = 1; i <= 10; i++) {
            allSlots.push(`${zone}-${i.toString().padStart(2, '0')}`);
        }
    });

    // 1. Lấy thông tin user và danh sách ô đỗ từ DB khi vừa vào trang
    useEffect(() => {
        // Lấy thông tin từ localStorage lúc đăng nhập (phải có id để lưu vào DB)
        const user = JSON.parse(localStorage.getItem('user') || '{}');
        const profile = JSON.parse(localStorage.getItem('userProfile') || '{}');

        setUserInfo({
            id: user.id || '',
            name: profile.fullName || profile.name || user.ten || 'Cư dân',
            room: profile.room_id || profile.room || '101'
        });

        fetchParkingStatus();
    }, []);

    // 2. Hàm lấy trạng thái bãi đỗ từ MySQL
    const fetchParkingStatus = async () => {
        try {
            const res = await axios.get('http://localhost:5000/api/parking/danh-sach');
            setAllSlotsData(res.data);
        } catch (error) {
            console.error("Lỗi lấy dữ liệu bãi đỗ:", error);
        }
    };

    // 3. Hàm xử lý Đăng ký thực tế vào MySQL
    const handleRegister = async () => {
        if (!selectedSlot) return;
        if (!userInfo.id) return alert("Không tìm thấy ID người dùng. Vui lòng đăng nhập lại!");

        setLoading(true);
        try {
            // GỬI DỮ LIỆU LÊN BACKEND (SERVER SẼ LƯU VÀO MYSQL)
            const response = await axios.post('http://localhost:5000/api/parking/dang-ky', { 
                ma_o: selectedSlot, 
                id_nguoi_dung: userInfo.id 
            });

            if (response.status === 200) {
                alert(`Chúc mừng! Bạn đã đăng ký thành công vị trí ${selectedSlot}`);
                fetchParkingStatus(); // Load lại giao diện để cập nhật màu ô vừa chọn
            }
        } catch (error) {
            const msg = error.response?.data?.message || "Đăng ký thất bại!";
            alert(msg);
        } finally {
            setLoading(false);
        }
    };

    // Tìm xem ô đang chọn đã có người đặt chưa (dựa vào dữ liệu từ DB)
    const slotDetail = allSlotsData.find(s => s.ma_o === selectedSlot);
    const isSelectedOccupied = slotDetail && slotDetail.trang_thai === 'DaSuDung';

    return (
        <div style={containerStyle} className="glass-card">
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🅿️ ĐĂNG KÝ BÃI ĐỖ XE</h2>
                <div style={userBadge}>
                    {userInfo.name} - {userInfo.room}
                </div>
            </div>

            <div style={contentWrapperStyle}>
                {/* SƠ ĐỒ BÃI ĐỖ (Cột trái) */}
                <div className="custom-scrollbar" style={sidebarStyle}>
                    {allSlots.map(slot => {
                        // Kiểm tra ô này trong DB có ai đặt chưa
                        const dbData = allSlotsData.find(s => s.ma_o === slot);
                        const isOccupied = dbData && dbData.trang_thai === 'DaSuDung';

                        return (
                            <div key={slot} onClick={() => setSelectedSlot(slot)}
                                style={{ 
                                    ...slotItemStyle,
                                    background: selectedSlot === slot ? '#8b5e5e' : (isOccupied ? '#f1f1f1' : '#fff'), 
                                    color: selectedSlot === slot ? '#fff' : (isOccupied ? '#ccc' : '#333'),
                                    border: selectedSlot === slot ? 'none' : '1px solid #eee',
                                    cursor: isOccupied ? 'not-allowed' : 'pointer'
                                }}>
                                {slot}
                            </div>
                        );
                    })}
                </div>

                {/* FORM ĐĂNG KÝ / CHI TIẾT (Cột phải) */}
                <div style={mainContentStyle}>
                    {loading ? (
                        <div style={statusMsg}>Đang xử lý dữ liệu...</div>
                    ) : selectedSlot ? (
                        <div style={{ animation: 'fadeIn 0.3s', height: '100%', display: 'flex', flexDirection: 'column' }}>

                            <div style={headerContainer}>
                                <span style={subTitleStyle}>VỊ TRÍ LỰA CHỌN</span>
                                <h1 style={slotNumberStyle}>{selectedSlot}</h1>
                            </div>

                            <div style={infoArea}>
                                {isSelectedOccupied ? (
                                    <div style={cardRegistered}>
                                        <div style={statusBadge}>ĐÃ ĐƯỢC ĐĂNG KÝ</div>
                                        <div style={{ marginTop: '20px' }}>
                                            <p style={labelStyle}>Trạng thái:</p>
                                            <p style={valueStyle}>Đã có cư dân sử dụng</p>
                                            <p style={{...labelStyle, marginTop: '15px'}}>ID Chủ sở hữu:</p>
                                            <p style={valueStyle}>{slotDetail.id_nguoi_thue}</p>
                                        </div>
                                    </div>
                                ) : (
                                    <div style={registerBox}>
                                        <div style={iconCircle}>✨</div>
                                        <h2 style={{ color: '#333', marginBottom: '10px' }}>Vị trí này còn trống</h2>
                                        <p style={{ color: '#777', fontSize: '14px', lineHeight: '1.6' }}>
                                            Bạn đang chọn vị trí <b>{selectedSlot}</b>.<br/>
                                            Nhấn nút bên dưới để xác nhận đăng ký cho phòng <b>{userInfo.room}</b>.
                                        </p>

                                        <button onClick={handleRegister} style={btnSubmit}>
                                            XÁC NHẬN ĐĂNG KÝ NGAY
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    ) : (
                        <div style={emptyState}>
                            <div style={{fontSize: '50px', opacity: 0.3}}>🅿️</div>
                            <p>Vui lòng chọn một vị trí trên sơ đồ <br/> để tiến hành đăng ký</p>
                        </div>
                    )}
                </div>
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(0,0,0,0.1); border-radius: 10px; }
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
            `}</style>
        </div>
    );
};

